package com.careflow.ai.clinical;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.flywaydb.core.Flyway;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.jdbc.core.JdbcTemplate;import com.fasterxml.jackson.databind.*;import com.careflow.common.exception.BusinessException;import static org.assertj.core.api.Assertions.*;import java.util.*;import java.util.concurrent.*;
@EnabledIfEnvironmentVariable(named="R6_DB_TESTS",matches="1")
class ClinicalPostgresTest {
 DriverManagerDataSource ds;JdbcTemplate jdbc;ClinicalStore store;ObjectMapper json=new ObjectMapper().findAndRegisterModules();UUID actor=UUID.randomUUID(),visit=UUID.randomUUID();
 @BeforeEach void open(){ds=new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:15432/careflow_r6_ai_test",System.getenv("R6_DB_USER"),System.getenv("R6_DB_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/voice-migration").load().migrate();jdbc=new JdbcTemplate(ds);jdbc.execute("TRUNCATE ai_guideline_sources,ai_clinical_interactions");store=new ClinicalStore(ds,json,new ClinicalCipher(Base64.getEncoder().encodeToString(new byte[32])),1);}
 ClinicalStore.Source draft(){return store.create("SYNTHETIC source","1","NOI_TONG_QUAT","https://example.org/fixture","synthetic alpha excerpt",true,UUID.randomUUID());}
 @Test void sourceReviewAndRetirementAreDurableAndVersioned(){var s=draft();assertThat(s.status()).isEqualTo("DRAFT");store.review(s.id(),actor,s.hash());var restarted=new ClinicalStore(ds,json,new ClinicalCipher(Base64.getEncoder().encodeToString(new byte[32])),1);assertThat(restarted.source(s.id()).reviewer()).isEqualTo(actor);assertThat(restarted.retire(s.id()).status()).isEqualTo("RETIRED");assertThatThrownBy(()->store.review(s.id(),actor,s.hash())).isInstanceOf(BusinessException.class);}
 @Test void importerCannotApproveOwnSourceOrChangeHash(){var s=store.create("Fixture","1","NOI_TONG_QUAT","https://example.org/f","synthetic",true,actor);assertThatThrownBy(()->store.review(s.id(),actor,s.hash())).isInstanceOf(BusinessException.class);assertThatThrownBy(()->store.review(s.id(),UUID.randomUUID(),"b".repeat(64))).isInstanceOf(BusinessException.class);}
 @Test void concurrentReviewAcceptsExactlyOneReviewer()throws Exception{var s=draft();var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<Boolean>>of(()->{try{store.review(s.id(),UUID.randomUUID(),s.hash());return true;}catch(BusinessException e){return false;}},()->{try{store.review(s.id(),UUID.randomUUID(),s.hash());return true;}catch(BusinessException e){return false;}}));assertThat(results.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count()).isEqualTo(1);}finally{pool.shutdownNow();}}
 @Test void interactionContentIsEncryptedAndOwnerVisitBoundAcrossRestart(){UUID id=UUID.randomUUID();var body=json.createObjectNode().put("question","SYNTHETIC_SECRET_CONTENT");store.save(id,actor,visit,null,"a".repeat(64),body,"local-v1");String raw=jdbc.queryForObject("SELECT content_cipher FROM ai_clinical_interactions",String.class);assertThat(raw).doesNotContain("SYNTHETIC_SECRET_CONTENT");assertThat(store.read(id,actor,visit)).isEqualTo(body);assertThatThrownBy(()->store.read(id,UUID.randomUUID(),visit)).isInstanceOf(BusinessException.class);assertThatThrownBy(()->store.read(id,actor,UUID.randomUUID())).isInstanceOf(BusinessException.class);var next=new ClinicalStore(ds,json,new ClinicalCipher(Base64.getEncoder().encodeToString(new byte[32])),1);assertThat(next.read(id,actor,visit)).isEqualTo(body);}
 @Test void expiryDeletesContentAndPreventsRead(){UUID id=UUID.randomUUID();store.save(id,actor,visit,null,"a".repeat(64),json.createObjectNode().put("question","fixture"),"v1");jdbc.update("UPDATE ai_clinical_interactions SET expires_at=now()-interval '1 second'");assertThatThrownBy(()->store.read(id,actor,visit)).isInstanceOf(BusinessException.class);store.cleanup();assertThat(jdbc.queryForObject("SELECT count(*) FROM ai_clinical_interactions",Integer.class)).isZero();}
}
